#!/usr/bin/env python3
"""Groq JSONL Request Generator and Validator

An offline-first command line utility for generating and validating
JSONL chat requests before they are sent to Groq.

Usage: python groq_util.py [workspace_dir]

Reads template.json and jobs.jsonl from workspace, combines them,
normalizes messages, and outputs output.jsonl and report.json.
"""

import json
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


def load_json_file(path: Path) -> Any:
    """Load and parse a JSON file."""
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)


def load_jsonl_file(path: Path) -> List[Dict[str, Any]]:
    """Load and parse a JSONL file."""
    records = []
    with open(path, 'r', encoding='utf-8') as f:
        for line_num, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError as e:
                raise ValueError(f"Malformed JSON at line {line_num}: {e}")
    return records


def normalize_content(content: str) -> str:
    """Normalize message content by trimming whitespace."""
    if isinstance(content, str):
        return content.strip()
    return content


def normalize_messages(messages: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Normalize all messages in a conversation."""
    normalized = []
    for msg in messages:
        if not isinstance(msg, dict):
            raise ValueError(f"Invalid message format: {msg}")
        norm_msg = {
            'role': msg.get('role', ''),
            'content': normalize_content(msg.get('content', ''))
        }
        # Preserve any additional fields
        for key in msg:
            if key not in ('role', 'content'):
                norm_msg[key] = msg[key]
        normalized.append(norm_msg)
    return normalized


def merge_configs(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    """Deep merge override into base config. Override takes precedence."""
    result = base.copy()
    for key, value in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = merge_configs(result[key], value)
        else:
            result[key] = value
    return result


def validate_job(job: Dict[str, Any]) -> Tuple[bool, Optional[str]]:
    """Validate a job definition. Returns (is_valid, error_message)."""
    # Required: job_id
    if 'job_id' not in job or not job['job_id']:
        return False, "Missing or empty 'job_id'"

    # Required: messages array
    if 'messages' not in job:
        return False, "Missing 'messages' field"

    messages = job['messages']
    if not isinstance(messages, list):
        return False, "'messages' must be an array"

    if len(messages) == 0:
        return False, "'messages' array is empty"

    # Validate each message has a role
    for i, msg in enumerate(messages):
        if not isinstance(msg, dict):
            return False, f"Message {i} is not an object"
        if 'role' not in msg or not msg['role']:
            return False, f"Message {i} missing 'role'"

    return True, None


def process_job(job: Dict[str, Any], template: Dict[str, Any]) -> Dict[str, Any]:
    """Process a single job by merging with template and normalizing."""
    # Start with template as base
    result = merge_configs(template.copy(), job)

    # Normalize messages
    if 'messages' in result:
        result['messages'] = normalize_messages(result['messages'])

    return result


def main(workspace_dir: Optional[str] = None) -> int:
    """Main entry point."""
    workspace = Path(workspace_dir) if workspace_dir else Path('.')

    template_path = workspace / 'template.json'
    jobs_path = workspace / 'jobs.jsonl'
    output_path = workspace / 'output.jsonl'
    report_path = workspace / 'report.json'

    # Check required files exist
    if not template_path.exists():
        print(f"Error: {template_path} not found", file=sys.stderr)
        return 1

    if not jobs_path.exists():
        print(f"Error: {jobs_path} not found", file=sys.stderr)
        return 1

    # Load template
    try:
        template = load_json_file(template_path)
    except json.JSONDecodeError as e:
        print(f"Error: Malformed template.json: {e}", file=sys.stderr)
        return 1

    # Load jobs
    try:
        jobs = load_jsonl_file(jobs_path)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        return 1

    if not jobs:
        print("Warning: No jobs found in jobs.jsonl", file=sys.stderr)

    # Process jobs
    processed_requests = []
    errors = []
    stats = {
        'total_jobs': len(jobs),
        'successful': 0,
        'failed': 0,
        'job_ids_processed': []
    }

    for job in jobs:
        # Validate job
        is_valid, error_msg = validate_job(job)
        if not is_valid:
            errors.append({
                'job_id': job.get('job_id', 'unknown'),
                'error': error_msg
            })
            stats['failed'] += 1
            continue

        # Process job
        try:
            processed = process_job(job, template)
            processed_requests.append(processed)
            stats['successful'] += 1
            stats['job_ids_processed'].append(job['job_id'])
        except Exception as e:
            errors.append({
                'job_id': job.get('job_id', 'unknown'),
                'error': str(e)
            })
            stats['failed'] += 1

    # Write output.jsonl
    with open(output_path, 'w', encoding='utf-8') as f:
        for req in processed_requests:
            f.write(json.dumps(req, ensure_ascii=False) + '\n')

    # Write report.json
    report = {
        'workspace': str(workspace),
        'statistics': stats,
        'errors': errors
    }
    with open(report_path, 'w', encoding='utf-8') as f:
        json.dump(report, f, indent=2, ensure_ascii=False)

    # Print summary
    print(f"Processed {stats['successful']}/{stats['total_jobs']} jobs")
    if errors:
        print(f"Errors: {len(errors)}")
        for err in errors:
            print(f"  - {err['job_id']}: {err['error']}", file=sys.stderr)

    return 1 if errors else 0


if __name__ == '__main__':
    workspace = sys.argv[1] if len(sys.argv) > 1 else None
    sys.exit(main(workspace))
