    if not template_path.exists():
        print('Error: {} not found'.format(template_path), file=sys.stderr)
        return 1
    if not jobs_path.exists():
        print('Error: {} not found'.format(jobs_path), file=sys.stderr)
        return 1

    try:
        template = load_json_file(template_path)
    except json.JSONDecodeError as e:
        print('Error: Malformed template.json: {}'.format(e), file=sys.stderr)
        return 1

    try:
        jobs = load_jsonl_file(jobs_path)
    except ValueError as e:
        print('Error: {}'.format(e), file=sys.stderr)
        return 1

    if not jobs:
        print('Warning: No jobs found in jobs.jsonl', file=sys.stderr)

    processed_requests = []
    errors = []
    stats = {
        'total_jobs': len(jobs),
        'successful': 0,
        'failed': 0,
        'job_ids_processed': []
    }

    for job in jobs:
        is_valid, error_msg = validate_job(job)
        if not is_valid:
            errors.append({'job_id': job.get('job_id', 'unknown'), 'error': error_msg})
            stats['failed'] += 1
            continue
        try:
            processed = process_job(job, template)
            processed_requests.append(processed)
            stats['successful'] += 1
            stats['job_ids_processed'].append(job['job_id'])
        except Exception as e:
            errors.append({'job_id': job.get('job_id', 'unknown'), 'error': str(e)})
            stats['failed'] += 1

    with open(output_path, 'w', encoding='utf-8') as f:
        for req in processed_requests:
            f.write(json.dumps(req, ensure_ascii=False))
            f.write('\\n')

    report = {
        'workspace': str(workspace),
        'statistics': stats,
        'errors': errors
    }
    with open(report_path, 'w', encoding='utf-8') as f:
        json.dump(report, f, indent=2, ensure_ascii=False)

    print('Processed {}/{} jobs'.format(stats['successful'], stats['total_jobs']))
    if errors:
        print('Errors: {}'.format(len(errors)))
        for err in errors:
            print('  - {}: {}'.format(err['job_id'], err['error']), file=sys.stderr)

    return 1 if errors else 0

if __name__ == '__main__':
    workspace = sys.argv[1] if len(sys.argv) > 1 else None
    sys.exit(main(workspace))
